import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    d = int(next(it))
    a = [0] * n
    for i in range(1, n - 1):
        a[i] = int(next(it))
    x = [0] * n
    y = [0] * n
    for i in range(n):
        x[i] = int(next(it))
        y[i] = int(next(it))

    INF = 10**18
    dist = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            dist[i][j] = (abs(x[i] - x[j]) + abs(y[i] - y[j])) * d

    # dp[i] = minimum money needed to reach station i
    dp = [INF] * n
    dp[0] = 0
    used = [False] * n

    for _ in range(n):
        u = -1
        for i in range(n):
            if not used[i] and (u == -1 or dp[i] < dp[u]):
                u = i
        if u == -1 or dp[u] == INF:
            break
        used[u] = True
        for v in range(n):
            if used[v]:
                continue
            cost = dist[u][v]
            need = max(0, cost - a[u])
            cand = dp[u] + need
            if cand < dp[v]:
                dp[v] = cand

    print(dp[n - 1])

if __name__ == "__main__":
    main()
